def _help_smalltv(doc, lang):
    if 'id="smalltv"' in doc:
        return doc
    i = doc.find('<section id="rec"')
    return doc[:i] + _HELP_SMALLTV[lang] + doc[i:] if i >= 0 else doc


_hp_enstv = HELP_PAGE.find('<div lang="en">')
if _hp_enstv > 0:
    HELP_PAGE = _help_smalltv(HELP_PAGE[:_hp_enstv], "de") + _help_smalltv(HELP_PAGE[_hp_enstv:], "en")
